// Some portions generated by Claude
export type FilterableGraphNode = {
  kind: "iri" | "literal" | "blank";
  datatype?: string;
  language?: string;
};

export const NODE_KIND_FACET_ID = "__node_kind__";
export const DATATYPE_FACET_ID = "__literal_datatype__";
export const LANGUAGE_FACET_ID = "__literal_language__";
export const NO_LANGUAGE_VALUE_ID = "__no_language_tag__";

export const XSD_STRING =
  "http://www.w3.org/2001/XMLSchema#string";
export const RDF_LANG_STRING =
  "http://www.w3.org/1999/02/22-rdf-syntax-ns#langString";

export const NODE_KIND_LABELS = {
  iri: "IRI",
  literal: "Literal",
  blank: "Blank node",
} as const;

export function normalizedLiteralDatatype(
  node: FilterableGraphNode,
): string | null {
  if (node.kind !== "literal") return null;
  if (node.datatype) return node.datatype;
  return node.language ? RDF_LANG_STRING : XSD_STRING;
}

export function normalizedLiteralLanguage(
  node: FilterableGraphNode,
): string | null {
  if (node.kind !== "literal") return null;
  const language = node.language?.trim().toLocaleLowerCase();
  return language || NO_LANGUAGE_VALUE_ID;
}

export function intrinsicFacetValue(
  node: FilterableGraphNode,
  facetId: string,
): string | null | undefined {
  if (facetId === NODE_KIND_FACET_ID) return node.kind;
  if (facetId === DATATYPE_FACET_ID) {
    return normalizedLiteralDatatype(node);
  }
  if (facetId === LANGUAGE_FACET_ID) {
    return normalizedLiteralLanguage(node);
  }
  return undefined;
}

export function matchesIntrinsicFacet(
  node: FilterableGraphNode,
  facetId: string,
  selectedValues: ReadonlySet<string>,
): boolean | undefined {
  const value = intrinsicFacetValue(node, facetId);
  if (value === undefined) return undefined;
  return value !== null && selectedValues.has(value);
}

function escapeSparqlString(value: string) {
  return value
    .replace(/\\/g, "\\\\")
    .replace(/"/g, '\\"')
    .replace(/\r/g, "\\r")
    .replace(/\n/g, "\\n");
}

function isSafeSparqlIri(value: string) {
  return /^[A-Za-z][A-Za-z0-9+.-]*:[^<>"{}|^`\\\s]+$/.test(value);
}

export function intrinsicFacetSparqlFilter(
  facetId: string,
  selectedValues: ReadonlySet<string>,
  variable = "?focus",
): string | null {
  if (!selectedValues.size) return null;

  if (facetId === NODE_KIND_FACET_ID) {
    const tests = [...selectedValues].flatMap((value) => {
      if (value === "iri") return [`isIRI(${variable})`];
      if (value === "literal") return [`isLiteral(${variable})`];
      if (value === "blank") return [`isBlank(${variable})`];
      return [];
    });
    return tests.length ? `FILTER(${tests.join(" || ")})` : "FILTER(false)";
  }

  if (facetId === DATATYPE_FACET_ID) {
    const datatypes = [...selectedValues]
      .filter(isSafeSparqlIri)
      .map((value) => `<${value}>`);
    return datatypes.length
      ? `FILTER(isLiteral(${variable}) && DATATYPE(${variable}) IN (${datatypes.join(", ")}))`
      : "FILTER(false)";
  }

  if (facetId === LANGUAGE_FACET_ID) {
    const tests = [...selectedValues].map((value) =>
      value === NO_LANGUAGE_VALUE_ID
        ? `LANG(${variable}) = ""`
        : `LCASE(LANG(${variable})) = "${escapeSparqlString(value.toLocaleLowerCase())}"`,
    );
    return tests.length
      ? `FILTER(isLiteral(${variable}) && (${tests.join(" || ")}))`
      : "FILTER(false)";
  }

  return null;
}
